function page_terminal(): void
{
    $full = can('terminal_full');
    $cwd = $_SESSION['term_cwd_' . current_project_id()] ?? project_root();
    $js = <<<'JS'
(function(){var out=document.getElementById('tout'),inp=document.getElementById('tin'),cwd=document.getElementById('tcwd'),
csrf=document.getElementById('tcsrf').value,hist=[],hi=0;
function add(t,c){var s=document.createElement('span');if(c)s.className=c;s.textContent=t;out.appendChild(s);out.scrollTop=out.scrollHeight;}
inp.addEventListener('keydown',function(e){
 if(e.key==='ArrowUp'){if(hi>0){hi--;inp.value=hist[hi];}e.preventDefault();return;}
 if(e.key==='ArrowDown'){if(hi<hist.length-1){hi++;inp.value=hist[hi];}else{hi=hist.length;inp.value='';}e.preventDefault();return;}
 if(e.key==='l'&&e.ctrlKey){out.textContent='';e.preventDefault();return;}
 if(e.key!=='Enter')return;
 var cmd=inp.value;if(!cmd.trim())return;hist.push(cmd);hi=hist.length;inp.value='';
 if(cmd.trim()==='clear'){out.textContent='';return;}
 add(cwd.textContent+' $ '+cmd+'\n','t-cmd');inp.disabled=true;
 fetch('?a=term_exec',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf,'X-DPLY-Project':document.getElementById('tproj').value},body:JSON.stringify({cmd:cmd})})
 .then(function(r){return r.json();}).then(function(j){
   if(j.reauth){location.href='?a=reauth&return='+encodeURIComponent('?a=terminal');return;}
   if(j.output)add(j.output);if(j.error)add(j.error+'\n','t-err');
   if(typeof j.exit==='number'&&j.exit!==0)add('[exit '+j.exit+']\n','t-err');if(j.cwd)cwd.textContent=j.cwd;
 }).catch(function(err){add('Request failed: '+err+'\n','t-err');})
 .then(function(){inp.disabled=false;inp.focus();});
});
document.getElementById('tbox').addEventListener('click',function(){if(!window.getSelection().toString())inp.focus();});inp.focus();})();
JS;
    $allow = $full ? '' : '<details class="card"><summary>Allowed commands in restricted mode</summary><pre class="small">' . h(implode("\n", lines(setting('term_allow')))) . '</pre></details>';
    render('Terminal', page_head('Terminal ' . ($full ? badge('unrestricted shell', 'warn') : badge('restricted', 'ok')),
        'Non-interactive: each command runs to completion (timeout 5 min). git automatically uses the configured token / SSH key.'
        . ($full ? ' The active SSH key path is in $DPLY_SSH_KEY.' : ' No shell: pipes, redirects and variables are not interpreted; ".." is not allowed.'))
        . '<div class="term" id="tbox"><div class="term-bar"><span class="term-dots"><i></i><i></i><i></i></span><span class="t">' . h(proc_user()) . '@' . h((string) (gethostname() ?: 'server'))
        . '</span><span>' . ($full ? 'sh' : 'restricted') . '</span></div><div class="term-out" id="tout" aria-live="polite"></div><div class="term-in"><span class="cwd" id="tcwd" title="' . h($cwd) . '">' . h($cwd) . '</span><span style="color:#5e697a">$</span>'
        . '<input id="tin" type="text" autocomplete="off" autocapitalize="off" spellcheck="false" aria-label="Command"></div></div>'
        . '<div class="tips"><span><kbd>↑</kbd><kbd>↓</kbd> history</span><span><kbd>Ctrl</kbd>+<kbd>L</kbd> or <code>clear</code> to clear</span><span><code>cd</code> is remembered</span></div>'
        . '<input type="hidden" id="tcsrf" value="' . h(csrf_token()) . '"><input type="hidden" id="tproj" value="' . current_project_id() . '">' . $allow
        . '<script nonce="' . csp_nonce() . '">' . $js . '</script>');
}

function term_restricted_check(string $cmd): ?string
{
    if (str_contains($cmd, '..')) {
        return 'Restricted mode: ".." is not allowed.';
    }
    $c = (string) preg_replace('/\s+/', ' ', trim($cmd));
    foreach (lines(setting('term_allow')) as $p) {
        $p = (string) preg_replace('/\s+/', ' ', $p);
        if ($c === $p || str_starts_with($c, $p . ' ')) {
            return null;
        }
    }
    return 'Restricted mode: command is not in the allow-list.';
}

function do_term_exec(): void
{
    $in = json_decode((string) file_get_contents('php://input'), true);
    $cmd = is_array($in) ? trim((string) ($in['cmd'] ?? '')) : '';
    if ($cmd === '' || strlen($cmd) > 4000) {
        json_out(['error' => 'Empty or too long command.']);
    }
    $full = can('terminal_full');
    $root = project_root();
    $cwd = (string) ($_SESSION['term_cwd_' . current_project_id()] ?? $root);
    if (!is_dir($cwd) || (!$full && !path_within($cwd, $root))) {
        $cwd = $root;
    }

    if (preg_match('/^cd(?:\s+(.*))?$/s', $cmd, $m)) {
        $t = trim(trim($m[1] ?? ''), "\"'");
        $new = ($t === '' || $t === '~') ? $root : realpath($t[0] === '/' ? $t : "$cwd/$t");
        if ($new === false || !is_dir($new)) {
            json_out(['output' => "cd: no such directory: $t\n", 'exit' => 1, 'cwd' => $cwd]);
        }
        if (!$full && !path_within($new, $root)) {
            json_out(['error' => 'Restricted mode: cannot leave the project root.', 'exit' => 1, 'cwd' => $cwd]);
        }
        $_SESSION['term_cwd_' . current_project_id()] = $new;
        json_out(['output' => '', 'exit' => 0, 'cwd' => $new]);
    }

    if ($full) {
        $argv = ['/bin/sh', '-c', $cmd];
    } else {
        if ($err = term_restricted_check($cmd)) {
            audit('terminal.denied', $cmd);
            json_out(['error' => $err, 'exit' => 1, 'cwd' => $cwd]);
        }
        $argv = parse_args($cmd);
        if (!$argv) {
            json_out(['error' => 'Could not parse the command (unbalanced quotes?).', 'exit' => 1, 'cwd' => $cwd]);
        }
        $bin = $argv[0] === 'php' ? php_bin() : find_bin($argv[0]);
        if (!$bin) {
            json_out(['error' => "{$argv[0]}: command not found", 'exit' => 127, 'cwd' => $cwd]);
        }
        $argv[0] = $bin;
    }
    audit('terminal.exec', $cmd);
    session_write_close();
    $env = proc_env(true);
    if ($full && ($k = active_key_path())) {
        $env['DPLY_SSH_KEY'] = $k;
    }
    $r = run_proc($argv, $cwd, $env, 300);
    json_out(['output' => strip_ansi($r['out']) . ($r['timeout'] ? "\n[timed out after 300s]\n" : ''), 'exit' => $r['code'], 'cwd' => $cwd]);
}

// ---- src/64-page-env.php ---------------------------------------------

// ============================================================================
//  .env editor
// ============================================================================

function dotenv_path(): string
{
    return project_root() . '/.env';
}

function env_validate(string $content): array
{
    $errs = [];
    $seen = [];
    $inQuote = false;
    $startLine = 0;
    foreach (explode("\n", $content) as $i => $line) {
        $n = $i + 1;
        if ($inQuote) {
            if (preg_match('/(?<!\\\\)"\s*(#.*)?$/', $line)) {
                $inQuote = false;
            }
            continue;
        }
        $t = trim($line);
        if ($t === '' || $t[0] === '#') {
            continue;
        }
        if (!preg_match('/^(?:export\s+)?([A-Za-z_][A-Za-z0-9_.]*)\s*=\s*(.*)$/', $t, $m)) {
            $errs[] = "Line $n: expected KEY=VALUE";
            continue;
        }
        if (isset($seen[$m[1]])) {
            $errs[] = "Line $n: {$m[1]} is already defined on line {$seen[$m[1]]}";
        }
        $seen[$m[1]] = $n;
        $v = $m[2];
        if ($v !== '' && $v[0] === '"') {
            if (!preg_match('/(?<!\\\\)"/', substr($v, 1))) {
                $inQuote = true;
                $startLine = $n;
            }
        } elseif ($v !== '' && $v[0] === "'") {
            if (!str_contains(substr($v, 1), "'")) {
                $errs[] = "Line $n: unterminated single quote";
            }
        } elseif (preg_match('/\s/', (string) preg_replace('/\s+#.*$/', '', $v))) {
            $errs[] = "Line $n: unquoted value contains whitespace — wrap it in double quotes";
        }
    }
    if ($inQuote) {
        $errs[] = "Line $startLine: unterminated double quote";
    }
    return $errs;
}

function env_parse_simple(string $content): array
{
    $out = [];
    foreach (explode("\n", $content) as $line) {
        if (preg_match('/^\s*(?:export\s+)?([A-Za-z_][A-Za-z0-9_.]*)\s*=(.*)$/', $line, $m)) {
            $out[$m[1]] = trim($m[2]);
        }
    }
    return $out;
}

function env_backups(): array
{
    $files = glob(env_backup_dir() . '/env-*') ?: [];
    rsort($files);
    return $files;
}

function page_env(): void
{
    $f = dotenv_path();
    $exists = is_file($f);
    $content = $exists ? (string) file_get_contents($f) : '';
    $hash = $exists ? sha1($content) : 'none';
    $note = '';
    if (isset($_GET['load'])) {
        $b = basename((string) $_GET['load']);
        $bf = env_backup_dir() . '/' . $b;
        if (preg_match('/^env-[0-9]{8}-[0-9]{6}-[a-f0-9]{6}$/', $b) && is_file($bf)) {
            $content = (string) file_get_contents($bf);
            $note = '<div class="flash warn">Backup <code>' . h($b) . '</code> loaded into the editor — review it and press Save to restore it.</div>';
        }
    } elseif (!$exists && is_file(project_root() . '/.env.example')) {
        $content = (string) file_get_contents(project_root() . '/.env.example');
        $note = '<div class="flash warn">No .env exists yet — the editor is pre-filled from .env.example. Saving creates .env.</div>';
    }
    $cached = is_file(project_root() . '/bootstrap/cache/config.php');
    $bk = '';
    foreach (array_slice(env_backups(), 0, 20) as $b) {
        $bn = basename($b);
        $bk .= '<tr><td><code>' . h($bn) . '</code></td><td style="white-space:nowrap">' . ago((int) filemtime($b)) . '</td><td><div class="row end"><a class="btn sm" href="?a=env&load=' . h(rawurlencode($bn)) . '">' . icon('download') . 'Load</a></div></td></tr>';
    }
    audit('env.view', 'Opened .env editor');
    $lineCount = $content === '' ? 0 : substr_count($content, "\n") + 1;
    render('.env', page_head('Environment', 'Edit ' . $f . ' — a timestamped backup is taken before every save.') . $note
        . ($cached ? '<div class="flash warn">Config is cached — changes take effect only after config:cache / config:clear (choose below).</div>' : '')
        . '<div class="grid-main"><form method="post" action="?a=env" class="card">' . csrf_field()
        . '<input type="hidden" name="op" value="save"><input type="hidden" name="hash" value="' . h($hash) . '">'
        . '<div class="card-h"><h2>' . icon('env') . '.env</h2><span class="small mute">' . $lineCount . ' lines</span></div>'
        . '<textarea name="content" rows="28" spellcheck="false" autocomplete="off" aria-label=".env contents">' . h($content) . '</textarea>'
        . '<div class="actions"><label class="chk" style="margin:0"><input type="checkbox" name="force" value="1"><span>Save even if validation reports problems</span></label>'
        . '<div class="row" style="margin-left:auto"><select name="after" style="width:auto" aria-label="After saving"><option value="config_cache"' . ($cached ? ' selected' : '') . '>Then run config:cache</option>'
        . '<option value="config_clear">Then run config:clear</option><option value="none"' . ($cached ? '' : ' selected') . '>Do nothing else</option></select>'
        . '<button class="primary" type="submit" data-confirm="Write these changes to .env?">' . icon('check') . 'Save .env</button></div></div></form>'
        . '<div class="card"><h2>' . icon('clock') . 'Backups</h2>' . ($bk ? '<div class="tbl"><table>' . $bk . '</table></div>' : empty_state('clock', 'No backups yet.')) . '</div></div>');
}

function do_env(): void
{
    $f = dotenv_path();
    $content = str_replace(["\r\n", "\r"], "\n", (string) ($_POST['content'] ?? ''));
    if (strlen($content) > 512000) {
        flash('err', '.env content is too large.');
        redirect('?a=env');
    }
    if ($content !== '' && !str_ends_with($content, "\n")) {
        $content .= "\n";
    }
    $old = is_file($f) ? (string) file_get_contents($f) : null;
    $oldHash = $old === null ? 'none' : sha1($old);
    if (!hash_equals($oldHash, (string) ($_POST['hash'] ?? ''))) {
        flash('err', '.env was changed by someone else since you opened it. Your edit was NOT saved — reload and re-apply.');
        redirect('?a=env');
    }
    $errs = env_validate($content);
    if ($errs && empty($_POST['force'])) {
        flash('err', 'Not saved — validation problems (tick "Save even if…" to override):', implode("\n", array_slice($errs, 0, 30)));
        redirect('?a=env');
    }
    if ($old === $content) {
        flash('ok', 'No changes.');
        redirect('?a=env');
    }
    if ($old !== null) {
        $bf = env_backup_dir() . '/env-' . date('Ymd-His') . '-' . bin2hex(random_bytes(3));
        file_put_contents($bf, $old, LOCK_EX);
        @chmod($bf, 0600);
        foreach (array_slice(env_backups(), 50) as $extra) {
            @unlink($extra);
        }
    }
    $perms = $old !== null ? (fileperms($f) & 0777) : 0640;
    $tmp = dirname($f) . '/.env.dply-' . bin2hex(random_bytes(4));
    $written = file_put_contents($tmp, $content, LOCK_EX) !== false;
    if ($written) {
        @chmod($tmp, $perms);
        $written = @rename($tmp, $f);
    }
    if (!$written) {
        @unlink($tmp);
        flash('err', 'Could not write .env (permissions?).');
        redirect('?a=env');
    }
    $a = env_parse_simple($old ?? '');
    $b = env_parse_simple($content);
    $changed = [];
    foreach (array_unique(array_merge(array_keys($a), array_keys($b))) as $k) {
        if (($a[$k] ?? null) !== ($b[$k] ?? null)) {
            $changed[] = $k . (!isset($a[$k]) ? ' (added)' : (!isset($b[$k]) ? ' (removed)' : ''));
        }
    }
    audit('env.save', 'Changed keys: ' . (implode(', ', $changed) ?: '(formatting only)'));
    $after = (string) ($_POST['after'] ?? 'none');
    $pre = null;
    if (in_array($after, ['config_cache', 'config_clear'], true)) {
        $r = run_proc(artisan_cmd([$after === 'config_cache' ? 'config:cache' : 'config:clear']), project_root(), proc_env(), 120);
        $pre = $r['out'] . "\n[exit {$r['code']}]";
    }
    flash('ok', '.env saved. Changed: ' . (implode(', ', $changed) ?: 'formatting only') . ($errs ? ' (saved despite validation warnings)' : ''), $pre);
    redirect('?a=env');
}

